import{_ as a,o as r,c as e,a3 as o}from"./chunks/framework.Dj4Lt7vj.js";const g=JSON.parse('{"title":"查看账单","description":"","frontmatter":{"title":"查看账单"},"headers":[],"relativePath":"workspace/billing.md","filePath":"workspace/billing.md","lastUpdated":1787949005000}'),i={name:"workspace/billing.md"};function l(n,t,d,s,h,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="查看账单" tabindex="-1">查看账单 <a class="header-anchor" href="#查看账单" aria-label="Permalink to &quot;查看账单&quot;">​</a></h1><p>工作台的「账单」标签页和客户端的「账单」页内容一致：点数余额、套餐信息、消耗记录和兑换入口。</p><h2 id="页面内容" tabindex="-1">页面内容 <a class="header-anchor" href="#页面内容" aria-label="Permalink to &quot;页面内容&quot;">​</a></h2><ul><li><strong>当前可用点数</strong>：客服接待的套餐周期额度剩余 + 加油包剩余，不含运营助手额度。</li><li><strong>套餐信息</strong>：当前订阅的档位和周期。</li><li><strong>套餐与加油包</strong>：可购买档位的展示，实际开通方式见<a href="/aicare-docs/billing/purchase">购买套餐和加油包</a>。</li><li><strong>兑换码</strong>：输入销售提供的兑换码，立即到账，见<a href="/aicare-docs/billing/redeem">兑换码</a>。</li><li><strong>消耗记录</strong>：按动作类型和日期展示实际点数消耗明细。AI 回复的单次消耗不是固定值，以这里的记录为准。</li></ul><h2 id="消耗记录里的动作类型" tabindex="-1">消耗记录里的动作类型 <a class="header-anchor" href="#消耗记录里的动作类型" aria-label="Permalink to &quot;消耗记录里的动作类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>动作</th><th>含义</th></tr></thead><tbody><tr><td>AI 客服回复</td><td>AI 回复顾客消息</td></tr><tr><td>商品学习整理</td><td>每生成一份整理后的商品资料</td></tr><tr><td>整理回答内容</td><td>知识入库时的内容处理</td></tr><tr><td>挑选回答依据</td><td>回答时筛选参考资料</td></tr></tbody></table><p>各动作的计点规则见<a href="/aicare-docs/billing/points">点数怎么计算</a>。</p><h2 id="运营助手额度" tabindex="-1">运营助手额度 <a class="header-anchor" href="#运营助手额度" aria-label="Permalink to &quot;运营助手额度&quot;">​</a></h2><p>运营助手使用单独额度，按自然月累计并在每月 1 日重置。普通点数加油包不包含运营助手额度；是否开放和当月额度以当前套餐说明为准。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>余额和预期对不上？</strong> 按日期展开消耗记录，先看是哪类动作消耗的。商品学习按生成的商品资料计点，一次整理多个商品时，总消耗会随实际生成的资料数量增加。</p><p><strong>套餐点数和加油包点数先扣哪个？</strong> 先扣套餐周期内的额度，用完再扣加油包。</p><p><strong>周期没用完的点数会结转吗？</strong> 不会。套餐点数按 30 天周期发放，周期结束清零；加油包点数按自身有效期计算。</p>',13)])])}const b=a(i,[["render",l]]);export{g as __pageData,b as default};
